1: impl Shard {
2:     fn reserve_cancel_kill_terminalization(&mut self, run: RunId) -> RuntimeResult<()> {
3:         self.reserve_checked_out_run_slot(run)?;
4:         self.reserve_terminal_run_slot(run)
5:     }
6: 
7:     fn append_cancel_terminal_events(
8:         &mut self,
9:         run: RunId,
10:         reason: Option<String>,
11:         attempt: u16,
12:     ) -> RuntimeResult<()> {
13:         self.append_terminal_events_with_pending_action(
14:             run,
15:             RuntimeJournalEvent::RunCancelled {
16:                 run,
17:                 reason,
18:                 attempt,
19:             },
20:         )
21:     }
22: 
23:     fn append_kill_terminal_events(&mut self, run: RunId, attempt: u16) -> RuntimeResult<()> {
24:         self.append_terminal_events_with_pending_action(
25:             run,
26:             RuntimeJournalEvent::RunKilled { run, attempt },
27:         )
28:     }
29: 
30:     fn append_terminal_events_with_pending_action(
31:         &mut self,
32:         run: RunId,
33:         terminal: RuntimeJournalEvent,
34:     ) -> RuntimeResult<()> {
35:         match self.pending_action_get(run) {
36:             Some(ticket) if ticket.run == run => self.append_journal_events_atomically([
